mapper.select:
select * from () m

    and m.user_id = #{userId}
    and m.email like concat('%', #{email}, '%')
    and m.level = #{level}
    and m.status = #{status}
    and m.register_ip = #{registerIp}
    and date_format(m.register_time,'%Y%m%d') >= date_format(#{params.beginTime},'%Y%m%d')
    and date_format(m.register_time,'%Y%m%d') <= date_format(#{params.endTime},'%Y%m%d')
    and date_format(m.trial_end_time,'%Y%m%d') >= date_format(#{params.beginTrialTime},'%Y%m%d')
    and date_format(m.trial_end_time,'%Y%m%d') <= date_format(#{params.endTrialTime},'%Y%m%d')

order by m.register_time desc, m.user_id desc
